"""
Module providing the functionality to creat the ocp collector
configuration for all in cloud gNodeB deployments
"""


class CloudGnbOcpCollectorConfigurator:
    def create_cu_ocp_collector(self, ne_log_name):
        vcu_master_ssh = self.tl_config_information_provider.get_cu_master_node_ssh_details(node_id=self.ne_id)

        vcu_executor = {
            'host': vcu_master_ssh.addr,
            'user': vcu_master_ssh.username,
            'password': vcu_master_ssh.password}

        cu_namespace = self.tl_config_information_provider.get_cu_namespace(node_id=self.ne_id)

        find_command = (
            't=/tmp/vcu ;'
            'rm -rf $t ;'
            'mkdir $t ;'
            'cd $t ;'
            'oc adm must-gather > out1.log 2>&1 ;'
            f'oc adm inspect ns/{cu_namespace} > out2.log 2>&1 ;'
            'tar zcf vcu.tgz * ;'
            'echo $t/vcu.tgz')

        collector_name = f'{ne_log_name}_ocp_cu'
        cu_command_collector = {
            'name': collector_name,
            'find_command': find_command,
            'cleanup_command': 'rm -rf /tmp/vcu/',
            'executor': vcu_executor,
            'type': 'command'
        }
        self._collector_configuration_data.append(cu_command_collector)
        return collector_name

    def create_vdu_ocp_collector(self, ne_log_name, vdu_id=0):

        vdu_master_ssh = self.tl_config_information_provider.get_vdu_master_node_ssh_details(
            node_id=self.ne_id,
            vdu_id=vdu_id)
        vdu_executor = {
            'host': vdu_master_ssh.addr,
            'user': vdu_master_ssh.username,
            'password': vdu_master_ssh.password}

        vdu_namespace = self.tl_config_information_provider.get_vdu_namespace(node_id=self.ne_id, vdu_id=vdu_id)

        vdu_find_command = (
            't=/tmp/vdu ;'
            ' rm -rf $t ;'
            ' mkdir $t ;'
            ' cd $t ;'
            ' oc adm must-gather > out1.log 2>&1 ;'
            f' oc adm inspect ns/{vdu_namespace} ns/ran-nic-sw-controller '
            f' ns/nokia-sync-operator rannicconfigs/rannicconfig -n {vdu_namespace}> out2.log 2>&1 ;'
            ' tar zcf vdu.tgz * ;'
            ' echo $t/vdu.tgz ')

        collector_name = f'{ne_log_name}_ocp_vdu'
        vdu_command_collector = {
            'name': collector_name,
            'find_command': vdu_find_command,
            'cleanup_command': 'rm -rf /tmp/vdu',
            'executor': vdu_executor,
            'type': 'command'
        }
        self._collector_configuration_data.append(vdu_command_collector)

        return collector_name

    def add_ocp(self, ne_log_name, ne_log_configuration):

        collector_names = []
        for du_id in self.tl_config_information_provider.get_du_ids(self.ne_id):
            collector_names.append(self.create_vdu_ocp_collector(ne_log_name, vdu_id=0))

        collector_names.append(self.create_cu_ocp_collector(ne_log_name))

        ocp_collector = {
            'name': f'{ne_log_name}',
            'type': 'group',
            'members': collector_names
        }
        self._collector_configuration_data.append(ocp_collector)
